/bin/zsh -lc "node --input-type=module - <<'NODE'
const p = (zone) => new Intl.DateTimeFormat('en-CA', { timeZone: zone, timeZoneName: 'longOffset', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).format(new Date())
for (const zone of ['America/Los_Angeles', 'Asia/Makassar', 'Europe/Zurich', 'Asia/Kathmandu']) console.log(zone, p(zone))
NODE
find . -maxdepth 2 -type f -not -path './.pnpm-store/*' -print | sort"

